import{_ as i,o as t,c as g,a5 as h}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-1-push-notification/report3_spec.md","filePath":"feature/admin-management/3-10-1-push-notification/report3_spec.md"}'),o={name:"feature/admin-management/3-10-1-push-notification/report3_spec.md"};function l(r,n,a,s,u,c){return t(),g("div",null,[...n[0]||(n[0]=[h("<p><strong>3.10.1 Push Notification (Soạn và Gửi Thông Báo Hệ Thống)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) truy cập /admin/notifications và nhấn nút &quot;Soạn thông báo&quot;.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên hệ thống có quyền gửi thông báo tới người dùng toàn nền tảng.</li><li><strong>Purpose</strong>: Soạn và gửi thông báo hệ thống bằng EMAIL, ngay hoặc theo lịch. In-app và FCM để giai đoạn sau.</li><li><strong>Interface</strong>: Màn hình Thông báo Hệ thống (SCR-ADM-01), gồm soạn email, điều kiện người nhận, lưu nháp/lên lịch và lịch sử gửi.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN, nội dung và điều kiện người nhận; lưu nháp/lịch. Xác định người nhận tại thời điểm gửi thực tế, gửi qua dịch vụ email, lưu kết quả và audit; tránh sửa/hủy đua với gửi và tránh gửi trùng khi retry.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Màn hình Soạn và Gửi Thông Báo Hệ Thống (SCR-ADM-01):</p><ul><li>Left/Header: Sidebar điều hướng Admin; Top Header hiển thị tiêu đề trang &quot;Quản lý Thông báo Hệ thống&quot; và nút &quot;Soạn thông báo mới&quot;.</li><li>Center: Tiêu đề (5–200 ký tự), nội dung (10–5.000), loại System/Maintenance/Update/Promotion, đối tượng ALL/BY_PLAN/BY_ROLE, chọn gói từ catalog hoặc ADMIN/USER, URL tùy chọn, thời gian và múi giờ gửi. Phân biệt số người nhận ước tính với số thực tế.</li><li>Buttons: Gửi ngay, Lên lịch, Lưu nháp; chỉ sửa/hủy DRAFT hoặc SCHEDULED. Đã gửi không được thu hồi.</li><li>Footer: Lịch sử và phân trang; trạng thái DRAFT, SCHEDULED, SENT, FAILED hoặc CANCELLED; số gửi thành công/thất bại. SENT ghi nhận hoàn tất gửi, không có nghĩa người nhận đã đọc email.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: title (5–200), content (10–5.000), type (SYSTEM, MAINTENANCE, UPDATE, PROMOTION), targetType (ALL, BY_PLAN, BY_ROLE).</li><li><strong>Input optional</strong>: targetPlans (ID catalog, bắt buộc khi BY_PLAN), targetRoles (ADMIN/USER, bắt buộc khi BY_ROLE), scheduledAt (ISO có offset), actionUrl.</li><li><strong>System data</strong>: notificationId, senderId, channel=EMAIL, status (DRAFT, SCHEDULED, SENT, FAILED, CANCELLED), createdAt, sentAt, recipientCount, deliveryResults.</li><li><strong>Output</strong>: Bản ghi thông báo đã tạo kèm mã trạng thái HTTP 201 Created.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-35</strong>: Mọi thao tác phát thông báo yêu cầu quyền ADMIN đã xác thực.</li><li><strong>BR-57</strong>: Giai đoạn này chỉ gửi EMAIL; tiêu đề 5–200 và nội dung 10–5.000 ký tự. In-app và FCM ngoài phạm vi giai đoạn.</li><li><strong>BR-65</strong>: Xác định người nhận lúc gửi thực tế từ điều kiện đã lưu. Số xem trước chỉ là ước tính; không có người nhận vẫn hoàn tất với recipientCount=0.</li><li><strong>BR-82</strong>: BY_ROLE chỉ nhận ADMIN/USER; BY_PLAN dùng catalog subscription hiện có. Quyền thành viên Agency không phải system role.</li><li><strong>BR-57</strong>: Chỉ sửa/hủy DRAFT và SCHEDULED. Hủy đặt CANCELLED và ngăn gửi. Khi bắt đầu gửi phải khóa phiên bản; email đã gửi không thu hồi. Lưu lỗi từng người nhận và chỉ retry người chưa gửi được.</li><li><strong>BR-16</strong>: Audit tạo, sửa, lên lịch, hủy và gửi với người thực hiện, điều kiện, thời điểm và số người nhận thực tế.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN → Display: MSG39</li><li>Tiêu đề hoặc nội dung thông báo để trống → Display: MSG02</li><li>Độ dài tiêu đề hoặc nội dung vượt quá giới hạn cho phép → Display: MSG03</li><li>Thời gian hẹn giờ gửi không hợp lệ hoặc trong quá khứ → Display: MSG45</li><li>Gửi thông báo thành công → Display: MSG144</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin mở SCR-ADM-01 và soạn thông báo email.</li><li>Chọn điều kiện người nhận rồi lưu nháp, gửi ngay hoặc lên lịch trong tương lai.</li><li>Hệ thống kiểm tra nội dung, giá trị catalog và quyền ADMIN; lưu thao tác và audit.</li><li>Admin được sửa/hủy khi DRAFT hoặc SCHEDULED; worker kiểm tra phiên bản hiện tại trước gửi.</li><li>Lúc gửi thực tế, lấy người nhận theo vai trò/gói hiện tại và gửi email.</li><li>Ghi kết quả gửi, số người nhận thực tế, trạng thái và audit; cập nhật lịch sử.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Không có quyền ADMIN → MSG39; thiếu/sai dữ liệu bắt buộc → MSG02/MSG03.</li><li>2.a1: Lịch trong quá khứ hoặc thiếu điều kiện người nhận → lỗi kiểm tra; không gửi.</li><li>4.a1: Sửa/hủy sau khi bắt đầu gửi hoặc ở SENT/FAILED/CANCELLED → xung đột; không thu hồi email đã gửi.</li><li>5.a1: Email lỗi/toàn phần hoặc một phần → lưu kết quả và retry an toàn, không gửi lại người đã thành công.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Lưu nội dung, điều kiện người nhận, trạng thái vòng đời và kết quả gửi.</li><li>Chỉ người thỏa điều kiện lúc gửi nhận EMAIL; lịch đã hủy không được gửi.</li><li>Mọi thay đổi quản trị và lần gửi có audit bất biến.</li></ul>",14)])])}const d=i(o,[["render",l]]);export{p as __pageData,d as default};
